#!/usr/bin/env python3
"""Generate: the snapshot and the client's generated files.

Fetches the API's OpenAPI document and the sixteen RapidAPI listing documents, keeps them as the committed snapshot
under ``openapi/``, and writes the generated part of the package from that snapshot:

- ``src/uniquedomains/_generated/``: the client ``openapi-python-client`` writes (models and one module per operation);
- ``src/uniquedomains/_operations.py``: one entry per operation (id, method, path, tag, tier, plan, parameters, body,
  CSV form, text answer, the generated module);
- ``src/uniquedomains/_listings.py``: each listing's id, title, RapidAPI host and operation ids;
- ``src/uniquedomains/_namespaces.py``: the typed methods, one class per tag, one method per operation.

Modes:
    python scripts/generate.py                      fetch, write the snapshot, regenerate
    python scripts/generate.py --check              fetch and fail when the snapshot or a generated file differs
    python scripts/generate.py --offline            regenerate from the committed snapshot, no network
    python scripts/generate.py --offline --check    fail when a generated file differs from what the snapshot gives
    --base <url>                                    the API base (default UD_API_BASE, else https://api.unique.domains/v1)

The generator and its formatter are pinned (``pyproject.toml``, group ``generate``), so a check run on any machine
gives the same bytes. The generated files are committed: installing the package never needs the network.
"""

from __future__ import annotations

import argparse
import ast
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parent.parent
SNAPSHOT_FILE = ROOT / "openapi" / "v1.json"
LISTINGS_DIR = ROOT / "openapi" / "listings"
PACKAGE_DIR = ROOT / "src" / "uniquedomains"
GENERATED_DIR = PACKAGE_DIR / "_generated"
CONFIG_FILE = ROOT / "scripts" / "generator.yaml"
DEFAULT_BASE = "https://api.unique.domains/v1"
USER_AGENT = "uniquedomains-python-generate"

# The API's edge blocks an address after 10 reads of `/meta/openapi.json` in 10 seconds, and a run reads it 17 times.
READ_PAUSE_SECONDS = 1.1

METHODS = ("get", "post", "put", "patch", "delete")
LISTING_TITLE_PREFIX = "Unique Domains API: "
HEADER = (
    "# Generated by scripts/generate.py from openapi/v1.json. Do not edit by hand: run `python scripts/generate.py`.\n"
)

# Names a generated annotation may use that come from somewhere other than the models.
TYPING_NAMES = {"Any"}
BUILTIN_NAMES = {"str", "int", "float", "bool", "list", "dict", "None", "bytes", "tuple", "set"}
TYPES_NAMES = {"Unset", "UNSET", "File"}
STDLIB_NAMES = {"datetime": "    import datetime", "UUID": "    from uuid import UUID"}


# ----------------------------------------------------------------------------------------------------------------------
# Snapshot
# ----------------------------------------------------------------------------------------------------------------------


def serialize(value: Any) -> str:
    """One serialization for the snapshot: the server's key order, two spaces, a final newline (the Node SDK's form)."""
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def fetch_document(base: str, listing: str | None) -> Any:
    url = base.rstrip("/") + "/meta/openapi.json"
    if listing:
        url += "?" + urllib.parse.urlencode({"listing": listing})
    request = urllib.request.Request(url, headers={"Accept": "application/json", "User-Agent": USER_AGENT})
    try:
        with urllib.request.urlopen(request, timeout=60) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        retry = error.headers.get("retry-after")
        body = error.read().decode("utf-8", "replace")[:300]
        wait = f" (retry after {retry} s)" if retry else ""
        raise SystemExit(f"GET {url} answered {error.code}{wait}: {body}") from None


def listing_ids_of(document: Any) -> list[str]:
    """The listing ids, read from the `listing` enum of `get_openapi` (the document's own list)."""
    operation = document.get("paths", {}).get("/meta/openapi.json", {}).get("get", {})
    for param in operation.get("parameters", []):
        param = resolve_ref(document, param)
        if param.get("name") == "listing":
            ids = param.get("schema", {}).get("enum")
            if isinstance(ids, list) and ids:
                return [str(entry) for entry in ids]
    raise SystemExit("The document lists no listing ids (get_openapi has no `listing` enum).")


def reduce_listing(listing_id: str, document: Any) -> dict[str, Any]:
    """A listing's document reduced to what the client reads: its RapidAPI host and the operations it serves."""
    operations: list[str] = []
    hosts: set[str] = set()
    for item in document.get("paths", {}).values():
        for method in METHODS:
            operation = item.get(method)
            if not operation or not operation.get("operationId"):
                continue
            operations.append(operation["operationId"])
            if operation.get("x-rapidapi-host"):
                hosts.add(operation["x-rapidapi-host"])
    if len(hosts) != 1:
        raise SystemExit(f"Listing {listing_id}: expected one RapidAPI host, found {len(hosts)}.")
    title = str(document.get("info", {}).get("title", listing_id))
    title = title[len(LISTING_TITLE_PREFIX) :] if title.startswith(LISTING_TITLE_PREFIX) else title
    return {"id": listing_id, "title": title, "host": next(iter(hosts)), "operations": operations}


def fetch_snapshot(base: str) -> tuple[Any, list[dict[str, Any]]]:
    document = fetch_document(base, None)
    listings = []
    for listing_id in listing_ids_of(document):
        time.sleep(READ_PAUSE_SECONDS)
        listings.append(reduce_listing(listing_id, fetch_document(base, listing_id)))
    return document, listings


def read_snapshot() -> tuple[Any, list[dict[str, Any]]] | None:
    if not SNAPSHOT_FILE.exists():
        return None
    document = json.loads(SNAPSHOT_FILE.read_text(encoding="utf-8"))
    listings = [
        json.loads((LISTINGS_DIR / f"{entry}.json").read_text(encoding="utf-8")) for entry in listing_ids_of(document)
    ]
    return document, listings


# ----------------------------------------------------------------------------------------------------------------------
# Operations table
# ----------------------------------------------------------------------------------------------------------------------


def resolve_ref(document: Any, value: Any, seen: frozenset[str] = frozenset()) -> Any:
    if not isinstance(value, dict) or not isinstance(value.get("$ref"), str):
        return value
    ref = value["$ref"]
    if ref in seen:
        raise SystemExit(f"Cyclic $ref {ref}")
    match = re.fullmatch(r"#/components/(\w+)/(.+)", ref)
    target = document.get("components", {}).get(match.group(1), {}).get(match.group(2)) if match else None
    if target is None:
        raise SystemExit(f"Cannot follow {ref}")
    return resolve_ref(document, target, seen | {ref})


TEXT_JSON_PATHS = frozenset({"/meta/openapi.json"})


def answer_of(path: str) -> str:
    """`text` for the document, the plain text and the calendars: they answer a file, not the envelope (Node R1 decision 4).

    A `.txt` or `.ics` path is a file; a `.json` path only when it is the document itself, so a future envelope path
    ending in `.json` is not read as text by accident (review R3-18). A test holds the table to the Node SDK's four.
    """
    if re.search(r"\.(txt|ics)$", path) or path in TEXT_JSON_PATHS:
        return "text"
    if path.endswith(".json"):
        raise SystemExit(f"{path}: a .json path that is not the document; decide whether it answers a file")
    return "json"


def build_operations(document: Any) -> list[dict[str, Any]]:
    operations: list[dict[str, Any]] = []
    seen: set[str] = set()
    for path, item in document.get("paths", {}).items():
        for method in METHODS:
            operation = item.get(method)
            if not operation:
                continue
            op_id = operation.get("operationId")
            if not op_id or op_id in seen:
                raise SystemExit(f"{method.upper()} {path}: missing or repeated operationId")
            seen.add(op_id)
            declared = [
                resolve_ref(document, p) for p in [*item.get("parameters", []), *operation.get("parameters", [])]
            ]
            # An operation's parameter overrides the path item's parameter of the same name and location.
            params = [
                p
                for i, p in enumerate(declared)
                if not any(q["in"] == p["in"] and q["name"] == p["name"] for q in declared[i + 1 :])
            ]
            for param in params:
                if param["in"] not in ("path", "query"):
                    raise SystemExit(f"{op_id}.{param['name']}: parameters in {param['in']} are not supported")
            path_order = re.findall(r"\{(\w+)\}", path)
            ordered = []
            for name in path_order:
                declared_path = [p for p in params if p["in"] == "path" and p["name"] == name]
                if not declared_path:
                    raise SystemExit(f"{op_id}: {path} names {{{name}}} but declares no such path parameter")
                ordered.append(declared_path[0])
            ordered += [p for p in params if p["in"] == "query"]
            body = None
            if operation.get("requestBody"):
                request_body = resolve_ref(document, operation["requestBody"])
                schema = resolve_ref(
                    document, request_body.get("content", {}).get("application/json", {}).get("schema", {})
                )
                if schema.get("type") != "object":
                    raise SystemExit(f"{op_id}: the body is not a JSON object")
                body = {
                    "required": bool(request_body.get("required")),
                    "properties": list(schema.get("properties", {}).keys()),
                }
            success = operation.get("responses", {}).get("200", {}).get("content", {})
            operations.append(
                {
                    "id": op_id,
                    "method": method.upper(),
                    "path": path,
                    "tag": (operation.get("tags") or ["shared"])[0],
                    "tier": "keyed" if operation.get("x-tier") == "keyed" else "free",
                    "plan": operation.get("x-plan"),
                    "summary": operation.get("summary", ""),
                    "parameters": [
                        {"name": p["name"], "in": p["in"], "required": bool(p.get("required"))} for p in ordered
                    ],
                    "body": body,
                    "csv": "text/csv" in success,
                    "answer": answer_of(path),
                }
            )
    return operations


# ----------------------------------------------------------------------------------------------------------------------
# The generated client: run openapi-python-client, read what it wrote
# ----------------------------------------------------------------------------------------------------------------------


def run_generator(document: Any, work: Path) -> Path:
    """Runs the pinned generator on the document. Answers the folder holding the generated package."""
    source = work / "v1.json"
    source.write_text(serialize(document), encoding="utf-8")
    out = work / "generated"
    env = dict(os.environ)
    # The generator's post hooks call `ruff` from PATH: the interpreter's own, the pinned one.
    env["PATH"] = str(Path(sys.executable).parent) + os.pathsep + env.get("PATH", "")
    # A DeprecationWarning printed by one of the generator's own dependencies is not a missing part of the client.
    env["PYTHONWARNINGS"] = "ignore::DeprecationWarning"
    command = [
        sys.executable,
        "-m",
        "openapi_python_client",
        "generate",
        "--path",
        str(source),
        "--output-path",
        str(out),
        "--meta",
        "none",
        "--config",
        str(CONFIG_FILE),
    ]
    result = subprocess.run(command, env=env, capture_output=True, text=True)
    output = result.stdout + result.stderr
    # The generator's own warning, or a post hook it skipped, means a part of the client is missing or unformatted:
    # fail rather than ship a partial client. Matched on the generator's lines, not on any "Warning" (review R3-18).
    partial = any(line.startswith(("Warning(s) encountered", "Skipping ")) for line in output.splitlines())
    if result.returncode != 0 or partial:
        sys.stderr.write(output)
        raise SystemExit("openapi-python-client did not generate the whole document.")
    shutil.rmtree(out / ".ruff_cache", ignore_errors=True)
    return out


def ast_of(file: Path) -> ast.Module:
    return ast.parse(file.read_text(encoding="utf-8"))


def find_function(module: ast.Module, name: str) -> ast.FunctionDef:
    for node in module.body:
        if isinstance(node, ast.FunctionDef) and node.name == name:
            return node
    raise SystemExit(f"No function {name}")


def kwargs_literal(function: ast.FunctionDef) -> tuple[str, str]:
    """The method and the URL template of a generated `_get_kwargs`."""
    for node in ast.walk(function):
        if isinstance(node, ast.Dict):
            keys = [k.value for k in node.keys if isinstance(k, ast.Constant)]
            if "method" in keys and "url" in keys:
                values = dict(zip(keys, node.values, strict=False))
                method = values["method"]
                url = values["url"]
                if isinstance(url, ast.Call) and isinstance(url.func, ast.Attribute):
                    url = url.func.value
                if isinstance(method, ast.Constant) and isinstance(url, ast.Constant):
                    return str(method.value).upper(), str(url.value)
    raise SystemExit(f"{function.name}: no method and url literal")


def map_modules(generated: Path) -> dict[tuple[str, str], str]:
    """(METHOD, path template) to the generated module (`names.get_name`), read from each module's `_get_kwargs`."""
    modules: dict[tuple[str, str], str] = {}
    for file in sorted((generated / "api").glob("*/*.py")):
        if file.name == "__init__.py":
            continue
        method, url = kwargs_literal(find_function(ast_of(file), "_get_kwargs"))
        modules[(method, template_of(url))] = f"{file.parent.name}.{file.stem}"
    return modules


def template_of(path: str) -> str:
    """A path with its parameter names blanked: the generator renames them (`{requestId}` becomes `{request_id}`)."""
    return re.sub(r"\{[^}]*\}", "{}", path)


def names_in(node: ast.AST) -> set[str]:
    return {n.id for n in ast.walk(node) if isinstance(n, ast.Name)}


def union_members(node: ast.expr) -> list[ast.expr]:
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.BitOr):
        return union_members(node.left) + union_members(node.right)
    return [node]


def model_file(generated: Path, class_name: str) -> Path:
    """The file of a generated model class, found through `models/__init__.py`."""
    init = ast_of(generated / "models" / "__init__.py")
    for node in init.body:
        if isinstance(node, ast.ImportFrom) and any(alias.name == class_name for alias in node.names):
            return generated / "models" / f"{node.module}.py"
    raise SystemExit(f"Model {class_name} not found")


def data_annotation(generated: Path, class_name: str) -> ast.expr:
    """The annotation of an envelope model's `data` attribute."""
    for node in ast.walk(ast_of(model_file(generated, class_name))):
        if isinstance(node, ast.ClassDef) and node.name == class_name:
            for statement in node.body:
                if (
                    isinstance(statement, ast.AnnAssign)
                    and isinstance(statement.target, ast.Name)
                    and statement.target.id == "data"
                ):
                    return statement.annotation
    raise SystemExit(f"{class_name} has no data attribute")


def return_models(function: ast.FunctionDef) -> list[str]:
    """The success models of a generated `sync_detailed`: its `Response[...]` union without `Any` and `Problem`."""
    returns = function.returns
    if not (
        isinstance(returns, ast.Subscript) and isinstance(returns.value, ast.Name) and returns.value.id == "Response"
    ):
        raise SystemExit(f"{function.name}: unexpected return annotation")
    members = [ast.unparse(m) for m in union_members(returns.slice)]
    return [m for m in members if m not in ("Any", "Problem", "None")]


# ----------------------------------------------------------------------------------------------------------------------
# Sources
# ----------------------------------------------------------------------------------------------------------------------


def literal(value: Any) -> str:
    return repr(value)


def path_args(generated: Path, module: str) -> list[str]:
    """The positional arguments of a generated `_get_kwargs`: the path parameters, under the generator's names."""
    function = find_function(ast_of(generated / "api" / Path(*module.split(".")).with_suffix(".py")), "_get_kwargs")
    return [arg.arg for arg in function.args.posonlyargs + function.args.args]


def squash(name: str) -> str:
    return name.replace("_", "").lower()


def build_operations_source(
    document: Any, operations: list[dict[str, Any]], modules: dict[tuple[str, str], str], generated: Path
) -> str:
    lines = [
        HEADER,
        '"""The operation table: what `Client.request` and the typed methods read about each operation."""',
        "",
        "from __future__ import annotations",
        "",
        "from typing import Any, Final",
        "",
        f"API_DOCUMENT_VERSION: Final = {literal(document.get('info', {}).get('version', ''))}",
        f"API_PUBLIC_BASE: Final = {literal(document['servers'][0]['url'])}",
        "",
        "OPERATIONS: Final[dict[str, dict[str, Any]]] = {",
    ]
    for op in operations:
        module = modules.get((op["method"], template_of(op["path"])))
        if module is None:
            raise SystemExit(f"{op['id']}: no generated module for {op['method']} {op['path']}")
        args = {squash(arg): arg for arg in path_args(generated, module)}
        parameters = []
        for param in op["parameters"]:
            if param["in"] == "path":
                if squash(param["name"]) not in args:
                    raise SystemExit(f"{op['id']}: no generated argument for the path parameter {param['name']}")
                param = {**param, "arg": args[squash(param["name"])]}
            parameters.append(param)
        lines.append(f"    {literal(op['id'])}: {literal({**op, 'parameters': parameters, 'module': module})},")
    lines.append("}")
    return "\n".join(lines) + "\n"


def build_listings_source(listings: list[dict[str, Any]]) -> str:
    lines = [
        HEADER,
        '"""The sixteen RapidAPI listings: the eight APIs, then the eight focused ones, each with its host and operations."""',
        "",
        "from __future__ import annotations",
        "",
        "from typing import Any, Final",
        "",
        "LISTINGS: Final[tuple[dict[str, Any], ...]] = (",
    ]
    for listing in listings:
        lines.append(f"    {literal(listing)},")
    lines.append(")")
    return "\n".join(lines) + "\n"


def class_name_of(tag: str) -> str:
    return "".join(part.capitalize() for part in re.split(r"[_\-]", tag)) + "Api"


def build_namespaces_source(
    document: Any, operations: list[dict[str, Any]], modules: dict[tuple[str, str], str], generated: Path
) -> str:
    tag_titles = {tag["name"]: tag.get("description", "") for tag in document.get("tags", [])}
    by_tag: dict[str, list[dict[str, Any]]] = {}
    for op in operations:
        by_tag.setdefault(modules[(op["method"], template_of(op["path"]))].split(".")[0], []).append(op)

    model_names: set[str] = set()
    classes: list[str] = []
    for tag, ops in by_tag.items():
        title = tag_titles.get(tag, "").split(": ")[0] or tag
        methods: list[str] = []
        for op in ops:
            module_path = modules[(op["method"], template_of(op["path"]))]
            file = generated / "api" / Path(*module_path.split(".")).with_suffix(".py")
            tree = ast_of(file)
            get_kwargs = find_function(tree, "_get_kwargs")
            sync_detailed = find_function(tree, "sync_detailed")

            params: list[str] = []
            passed: list[str] = []
            conversions: list[str] = []
            args = get_kwargs.args
            positional = args.posonlyargs + args.args
            defaults = [None] * (len(positional) - len(args.defaults)) + list(args.defaults)
            for arg, default in zip(positional, defaults, strict=True):
                annotation = ast.unparse(arg.annotation) if arg.annotation else "Any"
                model_names.update(names_in(arg.annotation) if arg.annotation else set())
                if annotation == "UUID":
                    annotation = "UUID | str"
                params.append(
                    f"{arg.arg}: {annotation}" + (f" = {ast.unparse(default)}" if default is not None else "")
                )
                passed.append(arg.arg)
            keyword: list[str] = []
            for arg, default in zip(args.kwonlyargs, args.kw_defaults, strict=True):
                # A projection answers partial rows, which the generated models (every member required) cannot
                # read: `fields` stays on `Client.request`, which answers decoded JSON.
                if arg.arg == "fields":
                    continue
                annotation_node = arg.annotation
                annotation = ast.unparse(annotation_node) if annotation_node else "Any"
                model_names.update(names_in(annotation_node) if annotation_node else set())
                if arg.arg == "body":
                    body_class = annotation.split(" | ")[0]
                    body_module = model_file(generated, body_class).stem
                    annotation = f"{annotation} | Mapping[str, Any]"
                    conversions.append(f"        body = _body(body, {literal(body_module)}, {literal(body_class)})")
                elif arg.arg == "include":
                    annotation = annotation.replace("str", "str | Sequence[str]", 1)
                    conversions.append(f"        {arg.arg} = _join({arg.arg})")
                # An optional parameter defaults to UNSET, never to the document's default: the method sends only
                # what the caller passed, and the server keeps its own defaults (review R3-10).
                keyword.append(f"{arg.arg}: {annotation}" + (" = UNSET" if default is not None else ""))
                passed.append(arg.arg)
            signature = ", ".join(["self", *params, *(["*", *keyword] if keyword else [])])

            if op["answer"] == "text":
                returns = "TextAnswer"
            else:
                envelopes = return_models(sync_detailed)
                data_types: list[str] = []
                for envelope in envelopes:
                    annotation = data_annotation(generated, envelope)
                    model_names.update(names_in(annotation))
                    rendered = ast.unparse(annotation)
                    if rendered not in data_types:
                        data_types.append(rendered)
                model_names.update(envelopes)
                returns = f"Answer[{' | '.join(envelopes)}, {' | '.join(data_types)}]"

            where = f"{op['method']} {op['path']}"
            grade = (
                "free"
                if op["tier"] == "free"
                else ("keyed, Investor plan" if op.get("plan") == "investor" else "keyed")
            )
            summary = op["summary"].replace('"""', "'''").replace("\\", "\\\\")
            methods.append(
                "\n".join(
                    [
                        f"    def {op['id']}({signature}) -> {returns}:",
                        f'        """{summary}',
                        "",
                        f"        `{where}`, {grade}. Reference: https://unique.domains/api/{op['id'].replace('_', '-')}",
                        '        """',
                        *conversions,
                        f"        return cast({literal(returns)}, self._client._call({literal(op['id'])}, {{{', '.join(f'{literal(name)}: {name}' for name in passed)}}}))",
                    ]
                )
            )
        classes.append(
            "\n".join(
                [
                    f"class {class_name_of(tag)}:",
                    f'    """{title}: the `{tag}` operations."""',
                    "",
                    "    def __init__(self, client: Client) -> None:",
                    "        self._client = client",
                    "",
                    "\n\n".join(methods),
                ]
            )
        )

    stdlib = [STDLIB_NAMES[name] for name in sorted(model_names & STDLIB_NAMES.keys())]
    model_names -= TYPING_NAMES | BUILTIN_NAMES | TYPES_NAMES | STDLIB_NAMES.keys() | {"Mapping", "Sequence"}
    type_imports = stdlib + [f"    from ._generated.models import {name}" for name in sorted(model_names)]
    lines = [
        HEADER,
        '"""The typed methods: one class per tag of the document, one method per operation, named by its operation id."""',
        "",
        "from __future__ import annotations",
        "",
        "from collections.abc import Mapping, Sequence",
        "from typing import TYPE_CHECKING, Any, cast",
        "",
        "from ._answer import Answer, TextAnswer",
        "from ._generated.types import UNSET, Unset",
        "from ._namespace_support import _body, _join",
        "",
        "if TYPE_CHECKING:",
        "    from ._client import Client",
        *type_imports,
        "",
        "__all__ = ["
        + ", ".join(literal(name) for name in [*(class_name_of(tag) for tag in by_tag), "NamespacedClient"])
        + "]",
        "",
        "NAMESPACES: dict[str, str] = {"
        + ", ".join(f"{literal(tag)}: {literal(class_name_of(tag))}" for tag in by_tag)
        + "}",
        "",
        "",
        "\n\n\n".join(classes),
        "",
        "",
        "class NamespacedClient:",
        '    """The namespaces of a `Client`, one per tag of the document, bound by `_bind_namespaces`."""',
        "",
        *[f"    {tag}: {class_name_of(tag)}" for tag in by_tag],
        "",
        "    def _bind_namespaces(self, client: Client) -> None:",
        *[f"        self.{tag} = {class_name_of(tag)}(client)" for tag in by_tag],
    ]
    return "\n".join(lines) + "\n"


def ruff_format(files: dict[Path, str], work: Path) -> dict[Path, str]:
    """Formats the hand-generated sources with the pinned ruff, in a scratch folder, so the bytes never depend on taste."""
    scratch = work / "format"
    scratch.mkdir()
    names = {}
    for index, (target, content) in enumerate(files.items()):
        file = scratch / f"f{index}_{target.name}"
        file.write_text(content, encoding="utf-8")
        names[target] = file
    ruff = [sys.executable, "-m", "ruff"]
    config = ["--config", str(ROOT / "pyproject.toml")]
    subprocess.run([*ruff, "check", "--fix-only", "--quiet", *config, str(scratch)], check=True)
    subprocess.run([*ruff, "format", "--quiet", *config, str(scratch)], check=True)
    return {target: file.read_text(encoding="utf-8") for target, file in names.items()}


def build_files(document: Any, listings: list[dict[str, Any]]) -> dict[Path, str]:
    files: dict[Path, str] = {SNAPSHOT_FILE: serialize(document)}
    for listing in listings:
        files[LISTINGS_DIR / f"{listing['id']}.json"] = serialize(listing)
    with tempfile.TemporaryDirectory() as temp:
        work = Path(temp)
        generated = run_generator(document, work)
        for file in sorted(generated.rglob("*")):
            if file.is_file() and "__pycache__" not in file.parts:
                files[GENERATED_DIR / file.relative_to(generated)] = file.read_text(encoding="utf-8")
        operations = build_operations(document)
        modules = map_modules(generated)
        tables = {
            PACKAGE_DIR / "_operations.py": build_operations_source(document, operations, modules, generated),
            PACKAGE_DIR / "_listings.py": build_listings_source(listings),
            PACKAGE_DIR / "_namespaces.py": build_namespaces_source(document, operations, modules, generated),
        }
        files.update(ruff_format(tables, work))
    return files


# ----------------------------------------------------------------------------------------------------------------------
# Main
# ----------------------------------------------------------------------------------------------------------------------


def main() -> int:
    parser = argparse.ArgumentParser(description="Refresh the OpenAPI snapshot and regenerate the client.")
    parser.add_argument("--check", action="store_true", help="fail when a file differs instead of writing it")
    parser.add_argument("--offline", action="store_true", help="regenerate from the committed snapshot, no network")
    parser.add_argument("--base", default=os.environ.get("UD_API_BASE") or DEFAULT_BASE, help="the API base URL")
    options = parser.parse_args()

    previous = read_snapshot()
    if options.offline:
        if previous is None:
            raise SystemExit(
                "No committed snapshot to generate from: run `python scripts/generate.py` once with the network."
            )
        document, listings = previous
    else:
        document, listings = fetch_snapshot(options.base)

    files = build_files(document, listings)
    differing = [
        file for file, content in files.items() if not file.exists() or file.read_text(encoding="utf-8") != content
    ]
    # A file under the generated folder or a listing file the generator no longer writes is stale.
    owned = (
        [p for p in GENERATED_DIR.rglob("*") if p.is_file() and "__pycache__" not in p.parts]
        if GENERATED_DIR.exists()
        else []
    )
    owned += list(LISTINGS_DIR.glob("*.json")) if LISTINGS_DIR.exists() else []
    stale = [file for file in owned if file not in files]
    differing += stale

    if options.check:
        if not differing:
            print(
                "The generated files match the snapshot."
                if options.offline
                else "The snapshot matches the live document."
            )
            return 0
        listed = "\n".join(f"  {file.relative_to(ROOT)}" for file in differing[:40])
        more = f"\n  ... and {len(differing) - 40} more" if len(differing) > 40 else ""
        print(f"Out of date ({len(differing)} files):\n{listed}{more}", file=sys.stderr)
        print("Run `python scripts/generate.py` and commit the result.", file=sys.stderr)
        return 1

    for file in differing:
        if file in stale:
            file.unlink()
            continue
        file.parent.mkdir(parents=True, exist_ok=True)
        file.write_text(files[file], encoding="utf-8")
    print("Nothing changed." if not differing else f"Wrote {len(differing)} files.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
